insert into public.study_tests(id,title,subject,grade,level,path,questions) values('protisty-cykle-a-v1','Protisty — cykle rozwojowe · zestaw A','Biologia','2lo','rozszerzony','testy/biologia/protisty-cykle.html?zestaw=a','[{"no": 1, "question": "Pantofelek żyje w wodzie słodkiej. Które wyjaśnienie łączy jego budowę z tym środowiskiem?", "topic": "Osmoregulacja", "options": ["Woda napływa osmotycznie, a wodniczki tętniące usuwają jej nadmiar.", "Woda odpływa osmotycznie, a wodniczki tętniące uzupełniają jej brak.", "Chloroplasty produkują cukry potrzebne do usuwania wody.", "Ściana komórkowa zapobiega napływowi wody do komórki."], "correct": 0, "explanation": "Słodka woda jest zwykle hipotoniczna względem wnętrza pantofelka. Woda napływa przez osmozę; wodniczki tętniące usuwają jej nadmiar i chronią komórkę przed pęknięciem. Pantofelek nie ma chloroplastów ani ściany komórkowej."}, {"no": 2, "question": "Dlaczego pantofelek nie pobiera stałych cząstek pokarmu w dowolnym miejscu powierzchni?", "topic": "Pellikula i pokarm", "options": ["Pellikula ogranicza odkształcanie powierzchni; pokarm trafia do komórki przez cytostom.", "Ściana z chityny uniemożliwia powstawanie wodniczek pokarmowych.", "Chloroplasty wymagają pobierania pokarmu wyłącznie przez wić.", "Makronukleus zamyka błonę dla wszystkich cząstek."], "correct": 0, "explanation": "Pellikula utrzymuje określony kształt pantofelka i ogranicza odkształcanie jego powierzchni. Pobieranie pokarmu jest zlokalizowane w obrębie cytostomu, skąd trafia on do wodniczek pokarmowych."}, {"no": 3, "question": "Która para cech upodabnia protisty zwierzęce do zwierząt?", "topic": "Protisty zwierzęce", "options": ["Cudzożywność i brak ściany komórkowej.", "Samożywność i obecność chloroplastów.", "Brak jądra i obecność mureiny.", "Obecność chitynowej ściany i trawienie zewnętrzne."], "correct": 0, "explanation": "Protisty zwierzęce są heterotrofami i nie mają ściany komórkowej. Mają jądro, ponieważ są eukariontami. Obecność lizosomów sama nie rozstrzyga o podobieństwie wyłącznie do zwierząt."}, {"no": 4, "question": "Euglena ma światło, a potem trafia do ciemności z dostępnymi związkami organicznymi. Co wyjaśnia jej miksotrofizm?", "topic": "Miksotrofizm", "options": ["Może fotosyntetyzować, a w innych warunkach korzystać z gotowych związków organicznych.", "W świetle oddycha, a w ciemności przestaje prowadzić metabolizm.", "W ciemności zamienia mitochondria w chloroplasty.", "Zawsze wymaga pochłaniania innych komórek przez fagocytozę."], "correct": 0, "explanation": "Miksotrofizm oznacza możliwość łączenia autotrofii i heterotrofii. Euglena może fotosyntetyzować w świetle, a przy dostępności odpowiednich związków organicznych korzystać z nich heterotroficznie. Oddycha także w świetle."}, {"no": 5, "question": "Który zestaw zawiera sposoby rozmnażania bezpłciowego spotykane u protistów?", "topic": "Rozmnażanie bezpłciowe", "options": ["Podział komórki, fragmentacja plechy, wytwarzanie zarodników bezpłciowych.", "Zapłodnienie, oogamia, połączenie gamet.", "Koniugacja, zapłodnienie, powstawanie zygoty.", "Transkrypcja, translacja, replikacja DNA."], "correct": 0, "explanation": "Protisty mogą rozmnażać się bezpłciowo przez podział komórki, fragmentację plechy i zarodniki bezpłciowe. Mitoza jest podziałem jądra, a nie pełną nazwą każdego sposobu rozmnażania organizmu."}, {"no": 6, "question": "Jakie zdarzenie prowadziło do endosymbiozy wtórnej?", "topic": "Endosymbioza wtórna", "options": ["Eukariont pochłonął fotosyntetyzującego eukarionta, który nie został strawiony.", "Bakteria pochłonęła wirusa, który utworzył jądro.", "Eukariont pochłonął sinicę bezpośrednio, tworząc pierwotny chloroplast.", "Dwie gamety połączyły się i od razu utworzyły cztery błony chloroplastu."], "correct": 0, "explanation": "Endosymbioza wtórna dotyczy pochłonięcia eukarionta mającego już chloroplast. Pochłonięcie sinicy przez eukarionta odpowiada endosymbiozie pierwotnej."}, {"no": 7, "question": "Dlaczego protisty w tradycyjnym szkolnym podziale są grupą parafiletyczną?", "topic": "Klasyfikacja", "options": ["Obejmują wspólnego przodka, lecz nie wszystkich jego potomków.", "Obejmują wyłącznie organizmy bez wspólnego przodka.", "Obejmują wspólnego przodka i wszystkich jego potomków.", "Każdy protist jest jednokomórkowy i ma identyczny genom."], "correct": 0, "explanation": "Grupa parafiletyczna pomija część potomków wspólnego przodka. Tradycyjne protisty nie obejmują m.in. roślin, grzybów i zwierząt. Monofiletyczna grupa obejmuje wszystkich potomków."}, {"no": 8, "question": "Co najpewniej upodabnia fotosyntetyzującego protista roślinopodobnego do komórki roślinnej?", "topic": "Protisty roślinopodobne", "options": ["Obecność chloroplastów umożliwiających fotosyntezę.", "Brak jądra komórkowego.", "Obecność ściany z mureiny.", "Odżywianie wyłącznie przez fagocytozę."], "correct": 0, "explanation": "Chloroplasty i fotosynteza stanowią kluczowe podobieństwo. Wiele takich protistów ma ścianę, ale nie wszystkie. Skrobia nie jest uniwersalnym materiałem zapasowym wszystkich protistów roślinopodobnych."}, {"no": 9, "question": "Gamety są podobnej wielkości i obie ruchliwe. Jaki to typ łączenia gamet?", "topic": "Typy gamet", "options": ["Izogamia.", "Anizogamia.", "Oogamia.", "Fragmentacja."], "correct": 0, "explanation": "Izogamia obejmuje podobne gamety. W anizogamii gamety różnią się wielkością, a w szkolnym ujęciu obie są ruchliwe. W oogamii komórka jajowa jest duża i nieruchliwa."}, {"no": 10, "question": "Na schemacie zarodźca malarii mejoza występuje po powstaniu zygoty. Jaki jest to typ mejozy i dlaczego?", "topic": "Malaria: mejoza", "options": ["Postgamiczna — redukcja 2n → n następuje po zapłodnieniu.", "Pregamiczna — gamety powstają z diploidalnego organizmu przez mejozę.", "Pośrednia — sporofit tworzy zarodniki dla wielokomórkowego gametofitu.", "Mitoza — zapłodnienie nie zmienia liczby zestawów chromosomów."], "correct": 0, "explanation": "U zarodźca mejoza jest postgamiczna: następuje po zapłodnieniu, w cyklu obejmującym zygotę 2n. Nie ma wielokomórkowej przemiany pokoleń jak u listownicy."}, {"no": 11, "question": "Dlaczego człowiek jest żywicielem pośrednim zarodźca malarii?", "topic": "Malaria: żywiciele", "options": ["W człowieku pasożyt rozmnaża się bezpłciowo; rozmnażanie płciowe zachodzi w komarze.", "Człowiek jest większy od komara i ma cięższe objawy.", "Gamety łączą się w wątrobie człowieka.", "Komar tylko mechanicznie przenosi pasożyta, który nie rozwija się w jego ciele."], "correct": 0, "explanation": "O rodzaju żywiciela decyduje rodzaj rozmnażania pasożyta. U człowieka zachodzi namnażanie bezpłciowe, a w komarze rozmnażanie płciowe. Komar jest żywicielem ostatecznym."}, {"no": 12, "question": "Toxoplasma gondii rozmnaża się płciowo u kotowatych. Które uzasadnienie dotyczące człowieka jest poprawne?", "topic": "Toksoplazmoza: cykl", "options": ["Nie powstają u niego gamety pasożyta, ponieważ człowiek jest żywicielem pośrednim.", "Powstają u niego gamety, ponieważ człowiek jest ssakiem.", "Jest żywicielem ostatecznym, bo może mieć objawy choroby.", "Powstają u niego zygoty, ponieważ pasożyt przekracza łożysko."], "correct": 0, "explanation": "U Toxoplasma rozmnażanie płciowe zachodzi u kotowatych, będących żywicielami ostatecznymi. Człowiek jest żywicielem pośrednim. Możliwość przejścia przez łożysko nie oznacza rozmnażania płciowego."}, {"no": 13, "question": "W którym przejściu zaznaczonym na schemacie listownicy zachodzi mejoza?", "topic": "Listownica: mejoza", "options": ["1 → 2: w zarodniach sporofitu powstają haploidalne zarodniki.", "2 → 3: zarodnik rozwija się w gametofit.", "4 → plemniki: haploidalny gametofit tworzy gamety.", "6 → 7: zygota rozwija się w młody sporofit."], "correct": 0, "explanation": "Mejoza zachodzi w zarodniach sporofitu 2n podczas powstawania zarodników n, na przejściu 1 → 2. Rozwój zarodnika i zygoty odbywa się przez mitozy."}, {"no": 14, "question": "Przez jaki podział gametofit listownicy wytwarza gamety?", "topic": "Listownica: gamety i zarodniki", "options": ["Mitozę — gametofit i gamety mają po jednym zestawie chromosomów.", "Mejozę — gametofit ma dwa zestawy chromosomów.", "Zapłodnienie — gametofit łączy zarodniki.", "Fragmentację — gamety są fragmentami sporofitu."], "correct": 0, "explanation": "Haploidalny gametofit n wytwarza haploidalne gamety przez mitozę. Mejoza zachodzi wcześniej w sporoficie 2n przy wytwarzaniu zarodników."}, {"no": 15, "question": "Co uzasadnia heteromorficzną przemianę pokoleń u listownicy?", "topic": "Przemiana pokoleń", "options": ["Wielokomórkowe gametofity n i sporofit 2n różnią się budową; dominuje duży sporofit.", "Duży gametofit 2n i sporofit n są identyczne.", "W cyklu występują tylko jednokomórkowe gamety i zygota.", "Każde pokolenie powstaje wyłącznie przez zapłodnienie."], "correct": 0, "explanation": "U listownicy przemieniają się wielokomórkowe pokolenia: gametofit n i sporofit 2n. Różnią się budową; duża plecha to dominujący sporofit, a gametofity są drobne."}]'::jsonb) on conflict(id) do nothing;
insert into public.study_tests(id,title,subject,grade,level,path,questions) values('protisty-cykle-b-v1','Protisty — cykle rozwojowe · zestaw B','Biologia','2lo','rozszerzony','testy/biologia/protisty-cykle.html?zestaw=b','[{"no": 1, "question": "Pantofelka przeniesiono do środowiska izotonicznego. Jak zmieni się potrzeba pracy wodniczek tętniących?", "topic": "Osmoregulacja", "options": ["Zmniejszy się, bo nie będzie stałego napływu nadmiaru wody.", "Zwiększy się, bo woda będzie napływać szybciej.", "Wodniczki zaczną produkować wodę w fotosyntezie.", "Wodniczki przejmą trawienie pobranych bakterii."], "correct": 0, "explanation": "W środowisku izotonicznym nie ma stałego osmotycznego napływu nadmiaru wody. Potrzeba jej usuwania maleje. Wodniczki pokarmowe i tętniące pełnią różne funkcje."}, {"no": 2, "question": "Uszkodzenie rzęsek kierujących bakterie do cytostomu utrudnia pantofelkowi przede wszystkim…", "topic": "Pellikula i pokarm", "options": ["Pobieranie cząstek pokarmu i tworzenie wodniczek pokarmowych.", "Wytwarzanie tlenu w chloroplastach.", "Redukcję liczby chromosomów w sporoficie.", "Usuwanie wody przez ścianę komórkową."], "correct": 0, "explanation": "Rzęski w okolicy aparatu gębowego kierują cząstki do cytostomu. Ich uszkodzenie utrudnia odżywianie, a nie fotosyntezę czy osmoregulację."}, {"no": 3, "question": "Nieznany protist ma jądro, pobiera bakterie przez fagocytozę i nie ma ściany komórkowej. W szkolnym podziale najbardziej przypomina…", "topic": "Protisty zwierzęce", "options": ["Protisty zwierzęce.", "Protisty roślinopodobne fotosyntetyzujące.", "Bakterie chemoautotroficzne.", "Rośliny lądowe o ścianie celulozowej."], "correct": 0, "explanation": "Fagocytoza, cudzożywność i brak ściany komórkowej odpowiadają protistom zwierzęcym. Jądro wyklucza bakterie."}, {"no": 4, "question": "Który wynik doświadczenia potwierdza miksotrofizm eugleny?", "topic": "Miksotrofizm", "options": ["W świetle wykorzystuje CO₂, a bez światła rośnie przy dostępie do odpowiednich związków organicznych.", "Bez światła wytwarza tlen z wody, a w świetle nie prowadzi fotosyntezy.", "W obu warunkach pobiera wyłącznie gotowe związki organiczne.", "W obu warunkach nie pobiera węgla ani nie produkuje biomasy."], "correct": 0, "explanation": "Wykorzystanie CO₂ przy fotosyntezie wskazuje na autotrofię. Wzrost bez światła dzięki gotowym związkom organicznym wskazuje na heterotrofię. Razem świadczą o miksotrofizmie."}, {"no": 5, "question": "Fragment plechy protista odrywa się i rozwija w samodzielny organizm. Jak nazwać ten proces?", "topic": "Rozmnażanie bezpłciowe", "options": ["Fragmentacja — rozmnażanie bezpłciowe.", "Oogamia — rozmnażanie płciowe.", "Koniugacja — wymiana jąder.", "Mejoza — redukcja liczby zestawów chromosomów."], "correct": 0, "explanation": "Fragmentacja polega na rozwoju nowych osobników z fragmentów ciała. Nie wymaga łączenia gamet. Sama mejoza nie opisuje tego sposobu rozmnażania."}, {"no": 6, "question": "Chloroplast protista otaczają trzy lub cztery błony. Która hipoteza najlepiej wyjaśnia tę cechę?", "topic": "Endosymbioza wtórna", "options": ["Powstał po pochłonięciu fotosyntetyzującego eukarionta przez innego eukarionta.", "Powstał w wyniku połączenia czterech gamet.", "Jest mitochondrium, które zmieniło funkcję podczas mejozy.", "Jest bakterią, która wytworzyła trzy ściany z mureiny."], "correct": 0, "explanation": "Dodatkowe błony chloroplastów wielu protistów są śladem endosymbiozy wtórnej. Pochłonięty partner był eukariontem posiadającym chloroplast."}, {"no": 7, "question": "Ze wspólnej linii eukariontów wyodrębniono rośliny, grzyby i zwierzęta, a resztę nazwano protistami. Jaki jest problem tego podziału?", "topic": "Klasyfikacja", "options": ["Grupa protistów nie obejmuje wszystkich potomków jej wspólnego przodka.", "Protisty przestały mieć jądra komórkowe.", "Wszystkie protisty stały się prokariontami.", "Wszystkie grupy mają identyczną budowę i sposób odżywiania."], "correct": 0, "explanation": "Wyłączenie części potomków wspólnego przodka powoduje parafiletyczność tradycyjnej grupy protistów. Podział taksonomiczny nie zmienia budowy organizmów."}, {"no": 8, "question": "Uczeń twierdzi: „Każdy protist roślinopodobny magazynuje skrobię, więc to roślina”. Która poprawka jest trafna?", "topic": "Protisty roślinopodobne", "options": ["Materiały zapasowe są zróżnicowane, a podobieństwo nie oznacza przynależności do roślin.", "Wszystkie protisty magazynują tylko glikogen.", "Protisty fotosyntetyzujące nie mają chloroplastów.", "Obecność skrobi wyklucza fotosyntezę."], "correct": 0, "explanation": "Protisty fotosyntetyzujące mają różne materiały zapasowe, np. euglena paramylon. Sama wspólna cecha nie wystarcza do przypisania organizmu do roślin."}, {"no": 9, "question": "Na schemacie komórka jajowa jest duża i nieruchliwa, a plemnik mały i ruchliwy. Jest to…", "topic": "Typy gamet", "options": ["Oogamia.", "Izogamia.", "Anizogamia z obiema gametami ruchliwymi.", "Podział komórki."], "correct": 0, "explanation": "Oogamia jest szczególnym zróżnicowaniem gamet: duża nieruchliwa komórka jajowa i mały ruchliwy plemnik. Takie gamety występują u listownicy."}, {"no": 10, "question": "W cyklu zarodźca gamety n łączą się w zygotę 2n. Jaki proces przywraca fazę haploidalną?", "topic": "Malaria: mejoza", "options": ["Mejoza po zapłodnieniu, w organizmie komara.", "Mitoza zygoty w erytrocycie człowieka.", "Zapłodnienie w komórce wątroby.", "Fragmentacja diploidalnego gametofitu."], "correct": 0, "explanation": "Zapłodnienie daje 2n, a mejoza przywraca n. Etapy płciowe i mejoza w cyklu zarodźca zachodzą w komarze; u człowieka pasożyt namnaża się bezpłciowo."}, {"no": 11, "question": "Która kolejność etapów po zakażeniu człowieka odpowiada schematowi?", "topic": "Malaria: żywiciele", "options": ["Wątroba → erytrocyty → gametocyty pobierane przez komara.", "Erytrocyty → zapłodnienie w człowieku → wątroba.", "Gamety w skórze → zygota w wątrobie → komar.", "Komar → chloroplasty człowieka → gametofit."], "correct": 0, "explanation": "Sporozoity trafiają do wątroby. Powstałe merozoity zakażają erytrocyty. Część pasożytów tworzy gametocyty, które pobiera komar. Gametocyty to nie zygoty."}, {"no": 12, "question": "Zygota Toxoplasma jest 2n, a mejoza zachodzi po zapłodnieniu. Który opis łączy te fakty?", "topic": "Toksoplazmoza: cykl", "options": ["Mejoza jest postgamiczna i redukuje liczbę zestawów chromosomów z 2n do n.", "Mejoza jest pregamiczna i zwiększa liczbę zestawów z n do 2n.", "Mitoza zygoty redukuje 2n do n.", "Zapłodnienie zmniejsza liczbę zestawów z 2n do n."], "correct": 0, "explanation": "Mejoza po zapłodnieniu jest postgamiczna. Redukuje 2n do n. Zapłodnienie ma odwrotny efekt: łączy gamety n w zygotę 2n."}, {"no": 13, "question": "Jaką funkcję pełni mejoza w cyklu listownicy?", "topic": "Listownica: mejoza", "options": ["Wytwarza zarodniki n ze sporofitu 2n, rozpoczynając fazę gametofitu.", "Wytwarza zygotę 2n z gamet n.", "Wytwarza gamety ze sporofitu bez etapu gametofitu.", "Zmienia gametofit n w sporofit n."], "correct": 0, "explanation": "Sporofit 2n tworzy zarodniki n przez mejozę. Z zarodników przez mitozy rozwijają się gametofity. Mejoza jest tu pośrednia, a nie postgamiczna."}, {"no": 14, "question": "Który opis rozróżnia zarodnik i gametę listownicy?", "topic": "Listownica: gamety i zarodniki", "options": ["Zarodnik rozwija się bez łączenia z drugim zarodnikiem; gameta uczestniczy w zapłodnieniu.", "Zarodnik zawsze ma 2n, a gameta zawsze 4n.", "Obie komórki muszą się połączyć parami, aby rozpocząć rozwój.", "Gameta rozwija się w gametofit, a zarodnik tworzy zygotę."], "correct": 0, "explanation": "Zarodnik n rozwija się przez mitozy w gametofit. Gameta n łączy się z drugą gametą podczas zapłodnienia, dając zygotę 2n. Obie mają n, ale różne funkcje."}, {"no": 15, "question": "U innej brunatnicy gametofit n i sporofit 2n mają podobną budowę. Jak nazwać tę przemianę?", "topic": "Przemiana pokoleń", "options": ["Izomorficzna — pokolenia są podobne, choć różnią się fazą jądrową.", "Heteromorficzna — podobna budowa oznacza różne pokolenia.", "Postgamiczna — podobna budowa oznacza mejozę tuż po zapłodnieniu.", "Izogamia — nazwa dotyczy wyglądu sporofitu i gametofitu."], "correct": 0, "explanation": "Izomorficzna przemiana oznacza podobieństwo budowy pokoleń. Izogamia dotyczy gamet, nie pokoleń. Listownica ma przemianę heteromorficzną."}]'::jsonb) on conflict(id) do nothing;